/* --- slider-swiper.js --- */
(function($) {
    "use strict";


    $(window).on("load", function() { // makes sure the whole site is loaded 


	//slider for home slider 
	 var parallaxSlider;
    var parallaxSliderOptions = {
        speed: 1000,
        mousewheel: true,
        parallax: true,
        loop: true,
        pagination: {
            el: '.slide-full .parallax-slider .swiper-pagination',
            clickable: true
        },
        on: {
            init: function () {
                var swiper = this;
                for (var i = 0; i < swiper.slides.length; i++) {
                    $(swiper.slides[i])
                        .find('.bg-img')
                        .attr({
                            'data-swiper-parallax': 0.75 * swiper.width
                        });
                }
            },
            resize: function () {
                this.update();
            }
        },

        pagination: {
            el: '.slide-full .parallax-slider .swiper-pagination',
            type: 'fraction',
        },

        navigation: {
            nextEl: '.slide-full .parallax-slider .next-ctrl',
            prevEl: '.slide-full .parallax-slider .prev-ctrl'
        }
    };
    parallaxSlider = new Swiper('.slide-full .parallax-slider', parallaxSliderOptions);


		
    });


})(jQuery);;

/* --- work-process.js --- */
(function($) {
    "use strict";


    $(window).on("load", function() { // makes sure the whole site is loaded
        // img-box-slider slider  
        $('.work-process').slick({ 
            autoplay: true,
            dots: false,
            slidesToShow: 4,
            nextArrow: '<i class="fa fa-angle-right"></i>',
            prevArrow: '<i class="fa fa-angle-left"></i>',
            slidesToScroll: 4,
            arrows: false,
            autoplaySpeed: 2000,
            speed:1000,
            fade: false,
            pauseOnHover: true,
            pauseOnFocus: false,
            responsive: [{
                    breakpoint: 1199,
                    settings: {
                        slidesToShow: 3,
                        slidesToScroll: 1,
                        infinite: true,
                    }
                },
                {
                    breakpoint: 992,
                    settings: {
                        slidesToShow: 2,
                        slidesToScroll: 1,
                        infinite: true,
                    }
                },
                {
                    breakpoint: 767,
                    settings: {
                        slidesToShow: 1,
                        slidesToScroll: 1
                    }
                },
            ]
        });
    });

})(jQuery);;

/* --- imgbox-slider.js --- */
(function($) {
    "use strict";

        // img-box-slider slider  
        $('.img-box-slider').slick({ 
            autoplay: false,
            dots: true,
            slidesToShow: 4,
            nextArrow: '<i class="fa fa-angle-right"></i>',
            prevArrow: '<i class="fa fa-angle-left"></i>',
            slidesToScroll: 3, 
            arrows: false,
            autoplaySpeed: 3000,
            speed:800,
            fade: false,
            pauseOnHover: false,
            pauseOnFocus: false,
            responsive: [{
                breakpoint: 1199,
                settings: {
                    slidesToShow: 3,
                    slidesToScroll: 1,
                    infinite: true,
                    dots: false
                }
            },
            {
                breakpoint: 992,
                settings: {
                    slidesToShow: 2,
                    slidesToScroll: 1,
                    infinite: true,
                    dots: false
                }
            },
            {
                breakpoint: 767,
                settings: {
                    slidesToShow: 1,
                    slidesToScroll: 1,
                    dots: false
                }
            },
            ]
        });

        $(window).on('resize', function() {
        $('.img-box-slider').slick('resize');
        });

})(jQuery);;

